/**
 * 兼容旧路径：/cart-rescue/gdpr/ → /gdpr/
 * @author 恒哥
 */
import React, { useEffect } from 'react';
import { navigate } from 'gatsby';
import SEO from '../../components/SEO';

export default function GdprRedirect() {
  useEffect(() => {
    navigate('/gdpr/', { replace: true });
  }, []);
  return (
    <SEO title="GDPR" description="Redirecting…" pathname="/cart-rescue/gdpr" noindex />
  );
}
